const types={"brand-cover.png":"image/png","retail.js":"text/javascript; charset=utf-8","catalog/products.json":"application/json; charset=utf-8","gallery.js":"text/javascript; charset=utf-8","index.html":"text/html; charset=utf-8","logo.svg":"image/svg+xml","favicon.png":"image/png","robots.txt":"text/plain; charset=utf-8","sitemap.xml":"application/xml","style.css":"text/css; charset=utf-8","catalog.js":"text/javascript; charset=utf-8","product.js":"text/javascript; charset=utf-8"};
export default {async scheduled(_event,env,ctx){ctx.waitUntil(deliverInquiryNotifications(env));},async fetch(request,env,ctx){const u=new URL(request.url);if(u.pathname.startsWith('/api/account/')||u.pathname==='/api/inquiries'||u.pathname==='/api/newsletter'){try{return await customerApi(request,env,products,ctx);}catch{return new Response(JSON.stringify({message:'Customer services are temporarily unavailable.'}),{status:503,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});}}if(u.pathname==='/api/shipping/quote')return shippingQuote(request,env,products);if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405,headers:{Allow:'GET, HEAD'}});if(u.pathname.endsWith('/')&&u.pathname!=='/')return Response.redirect(u.origin+u.pathname.slice(0,-1)+u.search,301);const path=u.pathname==='/'?'index.html':u.pathname.slice(1);let f=Object.hasOwn(files,path)?files[path]:null;const service=renderServicePage(u.pathname);if(service)f={content:service,encoding:'utf-8',type:'text/html; charset=utf-8'};if(path.startsWith('products/')){const p=products.find(p=>p.url===u.pathname);if(p)f={content:renderProduct(p),encoding:'utf-8',type:'text/html; charset=utf-8'};}else if(path.startsWith('collections/')){const content=renderCollection(path.slice(12),files['index.html'].content);if(content)f={content,encoding:'utf-8',type:'text/html; charset=utf-8'};}if(!f)return new Response(request.method==='HEAD'?null:renderNotFound(),{status:404,headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','X-Robots-Tag':'noindex'}});const body=f.encoding==='base64'?Uint8Array.from(atob(f.content),c=>c.charCodeAt(0)):f.content;return new Response(request.method==='HEAD'?null:body,{headers:{'Content-Type':types[path]||f.type||'text/plain','Cache-Control':(f.type||['index.html','style.css','catalog.js','product.js','retail.js','logo.svg','favicon.png','sitemap.xml'].includes(path))?'public, max-age=0, must-revalidate':'public, max-age=3600','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','X-Frame-Options':'DENY','Permissions-Policy':'camera=(), microphone=(), geolocation=()'}});}};
